css:
.stage {
  --size: 160px; /* diameter — everything scales from this */
  --t: 20px; /* thickness  */
  --n: 18; /* rim facets — drop to 12 on low-end devices */
  --spin: 5s;

  --r: calc(var(--size) / 2 - 2px); /* facet ring radius */
  --seg: calc(
    2 * var(--r) * tan(180deg / var(--n)) + 1px
  ); /* facet chord + overlap */

  --hi: #fff2c4;
  --gold: #e2a52b;
  --mid: #b9781a;
  --lo: #6b4207;

  position: relative;
  width: var(--size);
  height: var(--size);
  perspective: 900px;
}

.coin {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  will-change: transform;
  animation: spin var(--spin) linear infinite;
}
@keyframes spin {
  to {
    transform: rotateY(1turn);
  }
}

/* ── the two faces ── */
.face {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  display: grid;
  place-items: center;
  backface-visibility: hidden;
  background: conic-gradient(
    from 200deg,
    var(--hi) 0deg,
    var(--gold) 40deg,
    var(--lo) 92deg,
    var(--hi) 148deg,
    var(--mid) 205deg,
    var(--lo) 252deg,
    var(--gold) 312deg,
    var(--hi) 360deg
  );
  box-shadow:
    inset 0 0 0 calc(var(--size) * 0.018) rgba(255, 244, 204, 0.45),
    inset 0 0 0 calc(var(--size) * 0.055) rgba(74, 45, 4, 0.3),
    inset 0 calc(var(--size) * 0.05) calc(var(--size) * 0.1)
      rgba(255, 250, 225, 0.16),
    inset 0 calc(var(--size) * -0.06) calc(var(--size) * 0.12)
      rgba(30, 18, 1, 0.45);
}
/* placed on the real Z axis — no scaleX(-1) patch needed */
.heads {
  transform: translateZ(calc(var(--t) / 2));
}
.tails {
  transform: translateZ(calc(var(--t) / -2)) rotateY(180deg);
}

/* recessed inner field */
.face::before {
  content: "";
  position: absolute;
  inset: calc(var(--size) * 0.1);
  border-radius: 50%;
  background: radial-gradient(
    circle at 32% 26%,
    rgba(255, 248, 220, 0.3),
    rgba(255, 248, 220, 0) 62%
  );
  box-shadow:
    inset 0 2px 4px rgba(30, 18, 1, 0.45),
    0 1px 0 rgba(255, 246, 214, 0.35);
}

.rupee {
  position: relative;
  font:
    700 calc(var(--size) * 0.42) / 1 "Segoe UI",
    Roboto,
    system-ui,
    "Noto Sans",
    Arial,
    sans-serif;
  color: #ffe9a8;
  text-shadow:
    0 calc(var(--size) * 0.006) 0 rgba(70, 42, 4, 0.9),
    0 calc(var(--size) * -0.004) 0 rgba(255, 250, 230, 0.55),
    0 calc(var(--size) * 0.02) calc(var(--size) * 0.03) rgba(25, 15, 0, 0.5);
}

.rays {
  position: relative;
  width: 56%;
  height: 56%;
  border-radius: 50%;
  background: repeating-conic-gradient(
    from 0deg,
    rgba(255, 247, 214, 0.42) 0 4deg,
    rgba(60, 36, 3, 0.3) 4deg 9deg
  );
  box-shadow: inset 0 0 0 2px rgba(70, 42, 4, 0.4);
}
.rays::after {
  content: "";
  position: absolute;
  inset: 34%;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, var(--hi), var(--mid));
  box-shadow: 0 1px 3px rgba(20, 12, 0, 0.6);
}

/* ── milled edge: a real cylinder, one facet per <i> ── */
.edge {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
}
.edge i {
  --a: calc(var(--i) * (360deg / var(--n)));
  position: absolute;
  left: 50%;
  top: 50%;
  width: var(--seg);
  height: var(--t);
  margin: calc(var(--t) / -2) 0 0 calc(var(--seg) / -2);
  transform: rotateZ(var(--a)) translateY(var(--r)) rotateX(-90deg);
  backface-visibility: hidden;
  background-image:
    /* lighting: facets facing up stay bright, cos() keeps it stable while spinning */ linear-gradient(
      rgb(0 0 0 / calc(0.62 - 0.62 * max(0, cos(var(--a))))) 0 0
    ),
    linear-gradient(rgba(255, 255, 255, 0.16), rgba(0, 0, 0, 0.34)),
    repeating-linear-gradient(
      90deg,
      var(--lo) 0 1px,
      var(--gold) 1px 2px,
      var(--hi) 2px 3px,
      var(--mid) 3px 4px
    );
}

/* ── contact shadow, squashes twice per turn ── */
.shadow {
  position: absolute;
  left: 50%;
  bottom: calc(var(--size) * -0.26);
  width: var(--size);
  height: calc(var(--size) * 0.12);
  translate: -50% 0;
  border-radius: 50%;
  filter: blur(6px);
  background: radial-gradient(
    closest-side,
    rgba(0, 0, 0, 0.6),
    rgba(0, 0, 0, 0)
  );
  animation: squash calc(var(--spin) / 2) linear infinite;
}
@keyframes squash {
  0%,
  100% {
    transform: scaleX(1);
    opacity: 0.55;
  }
  50% {
    transform: scaleX(0.14);
    opacity: 0.35;
  }
}

@media (prefers-reduced-motion: reduce) {
  .coin {
    animation: none;
    transform: rotateY(-22deg);
  }
  .shadow {
    animation: none;
    transform: scaleX(0.92);
  }
}
